     1	// Calls each check with hand-made resource properties, without the Pulumi engine or any cloud.
     2	// Proves the checks' logic; does NOT prove how the Pulumi CLI wires them in (type tokens, unknown
     3	// values during preview). Run: npm test.
     4	import * as assert from "node:assert/strict";
     5	import { policies } from "./policies";
     6	
     7	// The minimal part of ResourceValidationArgs the checks use. The Pulumi CLI builds the real one;
     8	// isType compares the class's Pulumi type token, as the generated resource classes do.
     9	type FakeArgs = {
    10	    type: string;
    11	    props: Record<string, unknown>;
    12	    isType: (cls: { __pulumiType?: string }) => boolean;
    13	    notApplicable: (reason?: string) => void;
    14	};
    15	type Validation = (args: FakeArgs, report: (m: string) => void) => void;
    16	
    17	function violations(policyName: string, type: string, props: Record<string, unknown>): string[] {
    18	    const policy = policies.find((p) => p.name === policyName)!;
    19	    const checks = ([] as unknown[]).concat(policy.validateResource) as Validation[];
    20	    const found: string[] = [];
    21	    const args: FakeArgs = {
    22	        type,
    23	        props,
    24	        isType: (cls) => cls.__pulumiType === type,
    25	        notApplicable: () => undefined,
    26	    };
    27	    for (const check of checks) check(args, (m) => found.push(m));
    28	    return found;
    29	}
    30	
    31	const cases: Array<[string, string, Record<string, unknown>, boolean]> = [
    32	    // [policy, Pulumi type token, props, expect a violation]
    33	    ["iam-no-wildcard-actions", "aws:iam/policy:Policy",
    34	        { policy: JSON.stringify({ Statement: [{ Effect: "Allow", Action: "*", Resource: "*" }] }) }, true],
    35	    ["iam-no-wildcard-actions", "aws:iam/rolePolicy:RolePolicy",
    36	        { policy: { Statement: [{ Effect: "Allow", Action: ["s3:*"], Resource: "*" }] } }, true],
    37	    ["iam-no-wildcard-actions", "aws:iam/role:Role",
    38	        { inlinePolicies: [{ name: "x", policy: JSON.stringify({ Statement: { Effect: "Allow", NotAction: "iam:*", Resource: "*" } }) }] }, true],
    39	    ["iam-no-wildcard-actions", "aws:iam/policy:Policy",
    40	        { policy: JSON.stringify({ Statement: [{ Effect: "Allow", Action: ["s3:GetObject"], Resource: "arn:aws:s3:::b/*" }] }) }, false],
    41	    ["iam-no-wildcard-actions", "aws:iam/policy:Policy",
    42	        { policy: JSON.stringify({ Statement: [{ Effect: "Deny", Action: "*", Resource: "*" }] }) }, false],
    43	    ["aurora-deletion-protection", "aws:rds/cluster:Cluster", { deletionProtection: false }, true],
    44	    ["aurora-deletion-protection", "aws:rds/cluster:Cluster", {}, true],
    45	    ["aurora-deletion-protection", "aws:rds/cluster:Cluster", { deletionProtection: true }, false],
    46	    ["s3-public-access-block-all-on", "aws:s3/bucketPublicAccessBlock:BucketPublicAccessBlock",
